const userMenuWithoutPush=userMenu;userMenu=function(){userMenuWithoutPush();const actions=$('uxLogout')?.parentElement;if(actions&&!$('uxPushOpen')){const b=document.createElement('button');b.id='uxPushOpen';b.className='ux-btn primary';b.textContent='🔔 Push-Benachrichtigungen';b.onclick=pushCenter;actions.insertBefore(b,$('uxLogout'));}};
