async function openServerReplacement(requestId){try{const r=await K.pushAdapter.getReplacement(requestId),closed=r.status!=='open';shell(`<div class="ux-pagebar"><button class="ux-btn secondary ux-back" id="uxRepBack">←</button><div><h1>Vertretungsanfrage</h1><p style="margin:3px 0;color:#6d6966">${fmtDate(r.service_date)} · ${String(r.start_time).slice(0,5)}–${String(r.end_time).slice(0,5)} Uhr</p></div><span></span></div><section class="ux-card"><h2>${esc(r.area)}</h2>${closed?note(r.status==='filled'?'Diese Vertretung wurde bereits übernommen.':'Diese Anfrage ist nicht mehr offen.','warning'):note('Wenn Sie zusagen, werden Sie verbindlich in den Dienstplan eingetragen. Die erste gültige Zusage erhält den Dienst.')}<div class="ux-actions"><button class="ux-btn secondary" id="uxRepNo" ${closed?'disabled':''}>Kann ich nicht übernehmen</button><button class="ux-btn good" id="uxRepYes" ${closed?'disabled':''}>✓ Dienst übernehmen</button></div><div id="uxRepState"></div></section>`,'home');$('uxRepBack').onclick=showRoleHome;if(!closed){$('uxRepNo').onclick=()=>answerServerReplacement(r.id,false);$('uxRepYes').onclick=()=>answerServerReplacement(r.id,true)}}catch(e){alert(e.message);showRoleHome()}}
